export class Effects{constructor(){this.items=[];this.shake=0;this.flash=0;this.waves=[]}burst(x,y,color,count=12,type='spark'){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=(type==='energy'?80:45)+Math.random()*240;this.items.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-40,life:.25+Math.random()*.38,max:.63,size:2+Math.random()*4,color,type})}}shockwave(x,y,color){this.waves.push({x,y,color,r:5,life:.34,max:.34})}update(dt){for(const e of this.items){e.life-=dt;e.x+=e.vx*dt;e.y+=e.vy*dt;e.vy+=typeGravity(e.type)*dt}this.items=this.items.filter(e=>e.life>0);for(const w of this.waves){w.life-=dt;w.r+=330*dt}this.waves=this.waves.filter(w=>w.life>0);this.shake=Math.max(0,this.shake-dt*28);this.flash=Math.max(0,this.flash-dt*2.8)}draw(ctx){for(const w of this.waves){ctx.globalAlpha=w.life/w.max;ctx.strokeStyle=w.color;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(w.x,w.y,w.r,w.r*.28,0,0,Math.PI*2);ctx.stroke()}for(const e of this.items){ctx.globalAlpha=Math.max(0,e.life/e.max);ctx.fillStyle=e.color;if(e.type==='energy'){ctx.shadowBlur=12;ctx.shadowColor=e.color}if(e.type==='speed'){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(Math.atan2(e.vy,e.vx));ctx.fillRect(0,0,e.size*4,2);ctx.restore()}else ctx.fillRect(e.x,e.y,e.size,e.size)}ctx.globalAlpha=1;ctx.shadowBlur=0}}
function typeGravity(t){return t==='energy'?-130:t==='speed'?0:500}
